// scripts/generate-art.ts
// Usage:
//   RELEASE_ID=9 npx tsx scripts/generate-art.ts                      ← batch all R9 cards
//   RELEASE_ID=9 NEW=1 npx tsx scripts/generate-art.ts                ← batch R9, skip if has art
//   RELEASE_ID=9 PICK=1 npx tsx scripts/generate-art.ts               ← persistent pick for R9
//   RELEASE_ID=9 START_ID=330 PICK=1 npx tsx scripts/generate-art.ts  ← pick from card 330
//   START_ID=316 PICK=1 npx tsx scripts/generate-art.ts               ← cross-release from 316
//   START_ID=316 NEW=1 PICK=1 npx tsx scripts/generate-art.ts         ← cross-release, skip if has art
import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';
import * as dotenv from 'dotenv';
import { exec } from 'child_process';
dotenv.config({ path: '.env.local' });

import sharp from 'sharp';
import { createClient } from '@supabase/supabase-js';
import { GoogleGenAI } from '@google/genai';

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY ?? process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);
const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY! });

const PICK_PORT = 3458;
const SAMPLES_DIR = path.join(process.cwd(), 'art-samples', 'generated');

// ── Style directives ──────────────────────────────────────────────────────

const R9_STYLE = `Dark cinematic graphic novel illustration in the style of Frank Miller — dramatic chiaroscuro shadows, moody and powerful, high contrast, cinematic noir atmosphere`;
const R7_STYLE = `Ancient Egyptian temple wall painting — flat hieroglyphic profile-view figures, rich lapis lazuli blues and gold leaf, terracotta and sand tones, bold black outlines, animal-headed deities rendered with divine authority, papyrus texture background`;

const R21_STYLE = `Authentic 1956 Topps baseball card illustration — vintage 1950s photographic quality, warm slightly faded print tones`;
const R21_SUFFIX = `Square 1:1 format, fill the entire frame edge to edge with the card composition.`;

const R8_STYLE  = `Luminous underwater oil painting — deep blue atmosphere, bioluminescent glow effects, painterly realism, shafts of light filtering down from above, dramatic depth, wonder and mystery`;
const R10_STYLE = `Soft watercolor children's book illustration — gentle color washes, warm pastels, Beatrix Potter warmth, visible paper texture, plush fabric texture, intimate and cozy`;
const R11_STYLE = `Abstract expressionist painting — bold gestural brushstrokes, Pollock and Rothko energy, rich layered pigments, painterly texture, museum-quality dynamism`;
const R12_STYLE = `Norman Rockwell / Saturday Evening Post illustration — warm nostalgic realism, golden tones, heartwarming Americana, soft edges, cozy domestic scene`;
const R13_STYLE = `Eastern European Jewish folk art, Judaica papercutting tradition — intricate symmetrical patterns, warm earthy colors, traditional handcrafted aesthetic, deeply ornamental`;
const R14_STYLE = `Japanese folk art in the mingei tradition — bold simplified shapes, earthy warm tones, handmade quality, dignified simplicity, wabi-sabi aesthetic`;
const R15_STYLE = `Retro 1960s WPA / national park poster style — screen-print look, limited bold colors (forest green, sunny yellow, sky blue), pine trees and lake, vintage summer camp badge energy`;
const R16_STYLE = `1930s Art Deco travel poster — bold flat color illustration, sunburst compositions, stylized landmarks, warm Mediterranean palette, vintage "Visit..." poster grandeur`;
const R17_STYLE = `Victorian kennel club / sporting dog portrait — lush oil painted background, dog rendered with dignity and personality, warm mahogany tones, British heritage sporting print`;
const R18_STYLE = `Bright editorial food illustration — appetizing overhead composition, vivid saturated food colors, modern clean food styling, editorial magazine quality`;
const R19_STYLE = `Jungle adventure movie poster illustration — dramatic atmospheric lighting, vivid saturated colors, epic cinematic scale, action-adventure energy`;
const R20_STYLE = `Lego brick mosaic art — the entire image is composed of visible Lego stud tiles, pixelated but clearly recognizable, clever trompe l'oeil, bright primary color palette`;
const R24_STYLE = `Bold flat cartoon illustration — clean thick black outlines, bright saturated colors with flat fills, zero gradients or shading, simple expressive character shapes, high contrast compositions, energetic and joyful, characters with clear distinct silhouettes, original illustration style`;
const r24Panda = (where: string, material: string) =>
  `Hidden easter egg: a tiny stuffed black-and-white panda with a big round head and large sparkly eyes is ${where}, rendered in the same tones as the surrounding ${material} so it blends in naturally. It occupies a very small area. It is NOT a subject — it is a hidden secret requiring careful inspection to find.`;
const r24Bunny = (where: string, material: string) =>
  `Hidden easter egg: a tiny sage-green stuffed bunny rabbit with floppy ears is ${where}, rendered in the same muted green tones as the surrounding ${material} so it blends in. It occupies a very small area. It is NOT a subject — it is a hidden secret requiring careful inspection to find.`;
const R22_STYLE = `Corporate Memphis flat design illustration — clean vector shapes, minimal color palette, friendly geometric figures, modern tech startup aesthetic, bold simple composition`;
const R23_STYLE = `Vintage Olympic Games poster illustration (1936–1948 style) — heroic silhouette, limited warm palette, monumental composition, timeless athletic grandeur`;

const SUFFIX = `Square 1:1 format, fill the entire frame edge to edge with no borders or empty margins, no text or letters anywhere in the image.`;

function panda(location: string, context: string) {
  return `Hidden easter egg: a tiny stuffed panda is ${location}. It is rendered in the same tones as the surrounding ${context} so it blends in. It occupies a very small area. It is NOT a subject — it is a hidden secret that requires careful inspection to find.`;
}

function bunny(location: string, context: string) {
  return `Hidden easter egg: a tiny all-aqua stuffed bunny is ${location}. It is rendered in the same tones as the surrounding ${context} so it blends in. It occupies a very small area. It is NOT a subject — it is a hidden secret that requires careful inspection to find.`;
}

