type CardEntry = { id: number; name: string; prompt: string; releaseNum: number; dbReleaseId: number };

function getAllPrompts(): CardEntry[] {
  return Object.entries(PROMPTS_BY_RELEASE)
    .sort(([a], [b]) => parseInt(a) - parseInt(b))
    .flatMap(([num, entry]) =>
      entry.prompts.map(p => ({ ...p, releaseNum: parseInt(num), dbReleaseId: entry.dbReleaseId }))
    );
}

// ── Core generation ───────────────────────────────────────────────────────

async function generateImage(prompt: string, attempt = 1): Promise<Buffer> {
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    config: { responseModalities: ['IMAGE', 'TEXT'] } as any,
  });
  const parts = response.candidates?.[0]?.content?.parts ?? [];
  const imagePart = parts.find((p: any) => p.inlineData?.mimeType?.startsWith('image/'));
  if (!imagePart?.inlineData?.data) {
    if (attempt >= 3) throw new Error('No image returned after 3 attempts');
    console.log(`  No image returned — retrying (attempt ${attempt + 1}/3)...`);
    await new Promise(r => setTimeout(r, 3000 * attempt));
    return generateImage(prompt, attempt + 1);
  }
  return Buffer.from(imagePart.inlineData.data, 'base64');
}

async function compress(pngBuffer: Buffer): Promise<Buffer> {
  return sharp(pngBuffer).webp({ quality: 82 }).toBuffer();
}

async function uploadCard(card: CardEntry, buffer: Buffer): Promise<void> {
  const outDir = `./art-output/release-${card.releaseNum}`;
  fs.mkdirSync(outDir, { recursive: true });
  const localPath = path.join(outDir, `${card.id}-${card.name.replace(/[^a-z0-9]/gi, '-')}.png`);
  fs.writeFileSync(localPath, buffer);

  const webp = await compress(buffer);
  const storagePath = `cards/release-${card.releaseNum}/${card.id}.webp`;
  const { error: uploadError } = await supabase.storage
    .from('card-art')
    .upload(storagePath, webp, { contentType: 'image/webp', upsert: true });
  if (uploadError) throw uploadError;

  const { data: urlData } = supabase.storage.from('card-art').getPublicUrl(storagePath);
  console.log(`  Saved: ${localPath} → ${(webp.length / 1024).toFixed(0)} KB (was ${(buffer.length / 1024).toFixed(0)} KB)`);
  const { error: dbError } = await supabase
    .from('cards')
    .update({ art_url: urlData.publicUrl })
    .eq('id', card.id);
  if (dbError) throw dbError;

  console.log(`  ✓ ${card.name} uploaded + DB updated`);
}

async function uploadVariantCard(card: CardEntry, buffer: Buffer, variantId: number): Promise<void> {
  const outDir = `./art-output/variant-${variantId}`;
  fs.mkdirSync(outDir, { recursive: true });
  const localPath = path.join(outDir, `${card.id}-${card.name.replace(/[^a-z0-9]/gi, '-')}.png`);
  fs.writeFileSync(localPath, buffer);

  const webp = await compress(buffer);
  const storagePath = `cards/variant-${variantId}/${card.id}.webp`;
  const { error: uploadError } = await supabase.storage
    .from('card-art')
    .upload(storagePath, webp, { contentType: 'image/webp', upsert: true });
  if (uploadError) throw uploadError;

  const { data: urlData } = supabase.storage.from('card-art').getPublicUrl(storagePath);
  console.log(`  Saved: ${localPath} → ${(webp.length / 1024).toFixed(0)} KB (was ${(buffer.length / 1024).toFixed(0)} KB)`);
  const { error: dbError } = await supabase
    .from('card_art_variants')
    .upsert(
      { card_id: card.id, art_variant_id: variantId, art_url: urlData.publicUrl },
      { onConflict: 'card_id,art_variant_id' }
    );
  if (dbError) throw dbError;

  console.log(`  ✓ ${card.name} variant uploaded + DB updated`);
}

async function generateAndUpload(card: CardEntry): Promise<void> {
  console.log(`Generating: ${card.name} (id=${card.id})`);
  const buffer = await generateImage(card.prompt);
  await uploadCard(card, buffer);
}

// ── Persistent pick server ────────────────────────────────────────────────

const PICK_HTML = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Art Picker</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:-apple-system,sans-serif;background:#0f0f13;color:#e8e8e8;padding:2rem}
h1{text-align:center;font-size:1.3rem;margin-bottom:.3rem}
.meta{text-align:center;font-size:.72rem;color:#555;margin-bottom:.4rem}
.attrs{text-align:center;margin:.3rem 0 .3rem;display:flex;align-items:center;justify-content:center;gap:.5rem;font-size:.95rem}
.effect-text{text-align:center;font-size:.82rem;color:#334155;margin:.2rem auto;max-width:520px}
.flavor-text{text-align:center;font-size:.78rem;color:#64748b;margin:.2rem auto .9rem;max-width:520px}
.grid{display:flex;gap:1.2rem;max-width:1020px;margin:0 auto;justify-content:center}
.card{flex:1;min-width:260px;max-width:310px;border-radius:10px;overflow:hidden;background:#1a1a24;border:2px solid transparent;cursor:pointer;transition:border-color .15s,transform .15s}
.card:hover{border-color:#3a5a8a;transform:translateY(-2px)}
.card.sel{border-color:#60a5fa;box-shadow:0 0 0 3px rgba(96,165,250,.25)}
.card img{width:100%;display:block;aspect-ratio:1;object-fit:cover}
.card-lbl{padding:.5rem;text-align:center;font-size:.8rem;color:#666}
.card.sel .card-lbl{color:#60a5fa}
.bar{text-align:center;margin-top:1.6rem;display:flex;gap:.75rem;justify-content:center;flex-wrap:wrap}
.btn-use{padding:.65rem 2.2rem;background:#2563eb;color:#fff;border:none;border-radius:8px;font-size:.95rem;font-weight:600;cursor:pointer;display:none}
.btn-use.show{display:inline-block}
.btn-skip{padding:.65rem 1.6rem;background:#374151;color:#9ca3af;border:none;border-radius:8px;font-size:.95rem;font-weight:600;cursor:pointer}
.btn-regen{padding:.65rem 1.6rem;background:transparent;color:#6b7280;border:1px solid #374151;border-radius:8px;font-size:.95rem;font-weight:600;cursor:pointer}
.btn-regen:hover{color:#d1d5db;border-color:#6b7280}
.center{text-align:center;padding:5rem 2rem}
.center h2{font-size:1.2rem;margin-bottom:.8rem}
.spinner{width:2rem;height:2rem;border:3px solid #333;border-top-color:#60a5fa;border-radius:50%;animation:spin 1s linear infinite;margin:.8rem auto}
@keyframes spin{to{transform:rotate(360deg)}}
.done h2{color:#60a5fa}
.uploading h2{color:#f59e0b}
.overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.75);z-index:100;align-items:flex-start;justify-content:center;padding:4rem 1rem;overflow-y:auto}
.overlay.show{display:flex}
.modal{background:#1a1a24;border:1px solid #2d2d3d;border-radius:12px;padding:1.5rem;width:min(760px,100%);display:flex;flex-direction:column;gap:1rem}
.modal h3{font-size:1rem;color:#e8e8e8;font-weight:600}
.modal textarea{min-height:220px;background:#0f0f13;color:#d1d5db;border:1px solid #374151;border-radius:6px;padding:.75rem;font-size:.78rem;line-height:1.6;font-family:ui-monospace,monospace;resize:vertical;width:100%}
.modal textarea:focus{outline:none;border-color:#3b82f6}
.modal-btns{display:flex;gap:.75rem;justify-content:flex-end}
.btn-gen{padding:.55rem 1.6rem;background:#2563eb;color:#fff;border:none;border-radius:7px;font-size:.9rem;font-weight:600;cursor:pointer}
.btn-gen:hover{background:#1d4ed8}
.btn-cancel{padding:.55rem 1.2rem;background:#374151;color:#9ca3af;border:none;border-radius:7px;font-size:.9rem;font-weight:600;cursor:pointer}
</style>
</head>
<body>
<div id="app"><div class="center"><div class="spinner"></div><h2>Loading...</h2></div></div>
<div class="overlay" id="overlay">
  <div class="modal">
    <h3>Edit prompt &mdash; generate 3 new variations</h3>
    <textarea id="prompt-ta" spellcheck="false"></textarea>
    <div class="modal-btns">
      <button class="btn-cancel" onclick="cancelRegen()">Cancel</button>
      <button class="btn-gen" onclick="submitRegen()">Generate new variations</button>
    </div>
  </div>
</div>
<script>
var lastTs=null,sel=null,currentPrompt=null;
function poll(){
  fetch('/api/state').then(function(r){return r.json();}).then(function(s){
    render(s);
    if(s.status!=='complete')setTimeout(poll,1500);
  }).catch(function(){setTimeout(poll,3000);});
}
function render(s){
  var app=document.getElementById('app');
  if(s.status==='complete'){
    app.innerHTML='<div class="center done"><h2>All cards complete!</h2><p style="color:#555;margin-top:.5rem">Press Ctrl+C to exit.</p></div>';
    return;
  }
  if(s.status==='uploading'){
    app.innerHTML='<div class="center uploading"><div class="spinner"></div><h2>Uploading '+(s.card?s.card.name:'...')+'...</h2></div>';
    return;
  }
  if(s.status==='generating'||s.status==='regenerating'){
    var label=s.status==='regenerating'?'Regenerating':'Generating';
    app.innerHTML='<div class="center"><div class="spinner"></div><h2>'+label+' '+(s.card?s.card.name:'...')+'...</h2>'+(s.status==='generating'?'<p style="color:#555;margin-top:.5rem">'+s.queuePos+' of '+s.queueTotal+'</p>':'')+'</div>';
    return;
  }
  if(s.status==='ready'){
    if(s.ts===lastTs)return;
    lastTs=s.ts;sel=null;
    if(s.card&&s.card.prompt)currentPrompt=s.card.prompt;
    var cards='';
    for(var i=1;i<=3;i++){
      cards+='<div class="card" data-n="'+i+'" onclick="pick('+i+')"><img src="/img/'+s.ts+'/'+i+'.png" alt="Variation '+i+'"><div class="card-lbl">Variation '+i+'</div></div>';
    }
    var a=s.card.attrs||{};
    var typeColor={creature:'#16a34a',item:'#2563eb',action:'#9333ea',event:'#dc2626'};
    var badge=a.type?'<span style="background:'+(typeColor[a.type]||'#64748b')+';color:#fff;padding:2px 10px;border-radius:99px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:.05em">'+a.type+'</span> ':' ';
    var valStr=a.value!=null?'<b>'+a.value+'</b>':a.operator?'<b>'+a.operator+'</b>':a.effect_type?'<b>'+a.effect_type+'</b>':'';
    var attrsLine='<p class="attrs">'+badge+valStr+'</p>';
    var effectLine=a.effect_text?'<p class="effect-text">'+a.effect_text+'</p>':'';
    var flavorLine=a.flavor_text?'<p class="flavor-text"><em>'+a.flavor_text+'</em></p>':'';
    app.innerHTML='<h1>Pick variation &mdash; '+s.card.name+'</h1>'
      +'<p class="meta">R'+s.card.releaseNum+' &middot; '+s.queuePos+' of '+s.queueTotal+' &middot; id='+s.card.id+'</p>'
      +attrsLine+effectLine+flavorLine
      +'<div class="grid">'+cards+'</div>'
      +'<div class="bar">'
      +'<button id="btn" class="btn-use" onclick="go()">Use variation <span id="n"></span></button>'
      +'<button class="btn-regen" onclick="openRegen()">Regenerate&hellip;</button>'
      +'<button class="btn-skip" onclick="skip()">Skip</button>'
      +'</div>';
  }
}
function pick(n){
  sel=n;
  document.querySelectorAll('.card').forEach(function(c){c.classList.remove('sel');});
  document.querySelector('[data-n="'+n+'"]').classList.add('sel');
  document.getElementById('n').textContent=n;
  document.getElementById('btn').classList.add('show');
}
function go(){
  if(!sel)return;
  fetch('/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sample:sel})});
  document.getElementById('app').innerHTML='<div class="center uploading"><div class="spinner"></div><h2>Uploading...</h2></div>';
  sel=null;lastTs=null;
}
function skip(){
  fetch('/skip',{method:'POST'});
  document.getElementById('app').innerHTML='<div class="center"><div class="spinner"></div><h2>Generating next card...</h2></div>';
  sel=null;lastTs=null;
}
function openRegen(){
  var ta=document.getElementById('prompt-ta');
  ta.value=currentPrompt||'';
  document.getElementById('overlay').classList.add('show');
  setTimeout(function(){ta.focus();ta.setSelectionRange(0,0);ta.scrollTop=0;},50);
}
function cancelRegen(){
  document.getElementById('overlay').classList.remove('show');
}
function submitRegen(){
  var p=document.getElementById('prompt-ta').value.trim();
  if(!p)return;
  document.getElementById('overlay').classList.remove('show');
  fetch('/regenerate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:p})});
  document.getElementById('app').innerHTML='<div class="center"><div class="spinner"></div><h2>Regenerating...</h2></div>';
  sel=null;lastTs=null;
}
document.addEventListener('keydown',function(e){if(e.key==='Escape')cancelRegen();});
poll();
</script>
</body>
</html>`;

type CardDbAttrs = {
  type: string;
  value: number | null;
  operator: string | null;
  effect_type: string | null;
  effect_text: string | null;
  flavor_text: string | null;
};

async function runPickServer(queue: CardEntry[]): Promise<void> {
  if (queue.length === 0) {
    console.log('No cards to pick — queue is empty.');
    return;
  }

  // Pre-fetch card attributes for display in the picker UI
  const cardIds = queue.map(c => c.id);
  const { data: cardRows } = await supabase
    .from('cards')
    .select('id, type, value, operator, effect_type, effect_text, flavor_text')
    .in('id', cardIds);
  const cardDbMap = new Map<number, CardDbAttrs>(
    (cardRows ?? []).map(r => [r.id, r as CardDbAttrs])
  );

  let idx = 0;
  let serverState: {
    status: 'generating' | 'ready' | 'uploading' | 'regenerating' | 'complete';
    card: CardEntry | null;
    ts: string;
    imagePaths: string[];
  } = { status: 'generating', card: queue[0], ts: '', imagePaths: [] };

  // Preload queue — up to 2 cards ahead, running concurrently
  type PreloadEntry = { cardIdx: number; promise: Promise<{ ts: string; imagePaths: string[] }> };
  const preloads: PreloadEntry[] = [];

  async function generateImagesFor(card: CardEntry, tag: string, overridePrompt?: string): Promise<{ ts: string; imagePaths: string[] }> {
    const prompt = overridePrompt ?? card.prompt;
    const ts = `${card.id}-${Date.now()}`;
    const outDir = path.join(SAMPLES_DIR, ts);
    fs.mkdirSync(outDir, { recursive: true });
    const paths: string[] = [];
    for (let i = 1; i <= 3; i++) {
      console.log(`  [${tag}] [${i}/3] Generating...`);
      const buf = await generateImage(prompt);
      const fp = path.join(outDir, `${i}.png`);
      fs.writeFileSync(fp, buf);
      paths.push(fp);
      console.log(`  [${tag}] [${i}/3] ✓`);
      if (i < 3) await new Promise(r => setTimeout(r, 1500));
    }
    return { ts, imagePaths: paths };
  }

  function startPreload(nextIdx: number): void {
    if (nextIdx >= queue.length) return;
    if (preloads.some(p => p.cardIdx === nextIdx)) return; // already in flight
    const next = queue[nextIdx];
    console.log(`\n[preload] Starting: ${next.name} (id=${next.id})`);
    const entry: PreloadEntry = {
      cardIdx: nextIdx,
      promise: generateImagesFor(next, `preload ${next.name}`).catch(err => {
        console.error(`[preload] Failed for ${next.name}:`, err);
        const i = preloads.indexOf(entry);
        if (i !== -1) preloads.splice(i, 1);
        return { ts: '', imagePaths: [] };
      }),
    };
    preloads.push(entry);
  }

  async function generateCurrent(): Promise<void> {
    if (idx >= queue.length) {
      serverState = { status: 'complete', card: null, ts: '', imagePaths: [] };
      console.log('\nAll cards done! Press Ctrl+C to exit.');
      return;
    }
    const card = queue[idx];
    serverState = { status: 'generating', card, ts: '', imagePaths: [] };

    let result: { ts: string; imagePaths: string[] } | null = null;

    try {
      const preloadIdx = preloads.findIndex(p => p.cardIdx === idx);
      if (preloadIdx !== -1) {
        // Preload already started (or done) — just await it
        console.log(`\nAwaiting preloaded: ${card.name} (id=${card.id}, R${card.releaseNum})`);
        result = await preloads[preloadIdx].promise;
        preloads.splice(preloadIdx, 1);
        // If the preload returned empty paths (error fallback), regenerate fresh
        if (result.imagePaths.length === 0) {
          console.log(`  Preload had no images — regenerating fresh`);
          result = await generateImagesFor(card, card.name);
        }
      } else {
        // No preload for this card — generate synchronously
        console.log(`\nGenerating 3 variations of: ${card.name} (id=${card.id}, R${card.releaseNum})`);
        result = await generateImagesFor(card, card.name);
      }
    } catch (err) {
      console.error(`\nFailed to generate ${card.name} after all retries — skipping.`);
      console.error(err);
      idx++;
      generateCurrent().catch(console.error);
      return;
    }

    serverState = { status: 'ready', card, ts: result.ts, imagePaths: result.imagePaths };
    console.log(`Ready — pick in browser: http://localhost:${PICK_PORT}`);

    // Kick off the next 2 cards in the background while the user reviews this one
    startPreload(idx + 1);
    startPreload(idx + 2);
  }

  // Start generating first card immediately, preload second card in background
  generateCurrent().catch(console.error);

  const server = http.createServer((req, res) => {
    if (req.method === 'GET' && req.url === '/') {
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(PICK_HTML);
      return;
    }

    if (req.method === 'GET' && req.url === '/api/state') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      const cardAttrs = serverState.card ? cardDbMap.get(serverState.card.id) ?? null : null;
      res.end(JSON.stringify({
        status: serverState.status,
        card: serverState.card
          ? { id: serverState.card.id, name: serverState.card.name, releaseNum: serverState.card.releaseNum, prompt: serverState.card.prompt, attrs: cardAttrs }
          : null,
        ts: serverState.ts,
        queuePos: idx + 1,
        queueTotal: queue.length,
      }));
      return;
    }

    if (req.method === 'GET' && req.url?.startsWith('/img/')) {
      const parts = req.url.slice(5).split('/');
      const fp = path.join(SAMPLES_DIR, parts[0], parts[1]);
      if (fs.existsSync(fp)) {
        res.writeHead(200, { 'Content-Type': 'image/png' });
        res.end(fs.readFileSync(fp));
      } else {
        res.writeHead(404); res.end();
      }
      return;
    }

    if (req.method === 'POST' && req.url === '/select') {
      let body = '';
      req.on('data', c => { body += c; });
      req.on('end', async () => {
        const { sample } = JSON.parse(body);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ ok: true }));

        const card = serverState.card!;
        const imagePaths = serverState.imagePaths;
        serverState = { ...serverState, status: 'uploading' };

        console.log(`\nSelected variation ${sample} — uploading ${card.name}...`);
        try {
          const buf = fs.readFileSync(imagePaths[sample - 1]);
          await uploadCard(card, buf);
        } catch (e) {
          console.error('Upload error:', e);
        }

        idx++;
        generateCurrent().catch(console.error);
      });
      return;
    }

    if (req.method === 'POST' && req.url === '/skip') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: true }));
      console.log(`\nSkipping ${serverState.card?.name ?? '(unknown)'}`);
      idx++;
      generateCurrent().catch(console.error);
      return;
    }

    if (req.method === 'POST' && req.url === '/regenerate') {
      let body = '';
      req.on('data', c => { body += c; });
      req.on('end', async () => {
        const { prompt } = JSON.parse(body);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ ok: true }));

        const card = { ...serverState.card!, prompt };
        serverState = { ...serverState, status: 'regenerating' };
        console.log(`\nRegenerating: ${card.name} (id=${card.id})...`);

        try {
          const result = await generateImagesFor(card, `regen ${card.name}`, prompt);
          serverState = { status: 'ready', card, ts: result.ts, imagePaths: result.imagePaths };
          console.log(`Regenerated — pick in browser: http://localhost:${PICK_PORT}`);
        } catch (err) {
          console.error(`Regeneration failed for ${card.name}:`, err);
          // Restore ready state with whatever images were previously shown
          serverState = { ...serverState, status: 'ready' };
        }
      });
      return;
    }

    res.writeHead(404); res.end();
  });

  server.listen(PICK_PORT, '127.0.0.1', () => {
    exec(`open "http://localhost:${PICK_PORT}"`);
    console.log(`\nBrowser picker → http://localhost:${PICK_PORT}`);
    console.log('Press Ctrl+C to stop.\n');
  });

  // Keep the process alive indefinitely
  await new Promise<never>(() => {});
}

// ── Main ──────────────────────────────────────────────────────────────────

async function main() {
  if (!process.env.GEMINI_API_KEY) { console.error('GEMINI_API_KEY not set in .env.local'); process.exit(1); }

  const hasReleaseId = !!process.env.RELEASE_ID;
  const releaseNum   = hasReleaseId ? parseInt(process.env.RELEASE_ID!, 10) : null;
  const startId      = process.env.START_ID ? parseInt(process.env.START_ID, 10) : null;
  const newOnly      = process.env.NEW === '1';
  const isPick       = process.env.PICK === '1';
  const variantId    = process.env.VARIANT_ID ? parseInt(process.env.VARIANT_ID!, 10) : null;

  // ── VARIANT mode ──────────────────────────────────────────────────────────
  if (variantId) {
    const { data: variant, error: variantErr } = await supabase
      .from('art_variants')
      .select('id, release_id, name, style')
      .eq('id', variantId)
      .single();
    if (variantErr || !variant) {
      console.error(`art_variant id=${variantId} not found`);
      process.exit(1);
    }

    const releaseEntry = Object.entries(PROMPTS_BY_RELEASE).find(
      ([, e]) => e.dbReleaseId === variant.release_id
    );
    if (!releaseEntry) {
      console.error(`No prompts registered for release_id=${variant.release_id}`);
      process.exit(1);
    }
    const [rNum, entry] = releaseEntry;

    let cards: CardEntry[] = entry.prompts.map(p => ({
      ...p,
      releaseNum: parseInt(rNum),
      dbReleaseId: entry.dbReleaseId,
      prompt: p.prompt.replace(/^[^.]+(?=\.)/, variant.style),
    }));

    if (newOnly) {
      const { data: existing } = await supabase
        .from('card_art_variants')
        .select('card_id')
        .eq('art_variant_id', variantId);
      const doneIds = new Set((existing ?? []).map((c: any) => c.card_id));
      const before = cards.length;
      cards = cards.filter(p => !doneIds.has(p.id));
      console.log(`Variant "${variant.name}": ${cards.length} cards (skipped ${before - cards.length} with existing art)`);
    } else {
      console.log(`\nVariant "${variant.name}": generating ${cards.length} cards\n`);
    }

    const failed: string[] = [];
    for (const card of cards) {
      try {
        console.log(`Generating: ${card.name} (id=${card.id})`);
        const buffer = await generateImage(card.prompt);
        await uploadVariantCard(card, buffer, variantId);
      } catch (err: any) {
        console.warn(`  ⚠ SKIPPED ${card.name} (id=${card.id}): ${err?.message ?? err}`);
        failed.push(`${card.name} (id=${card.id})`);
      }
      await new Promise(r => setTimeout(r, 1500));
    }
    if (failed.length > 0) {
      console.log(`\nFailed cards (${failed.length}): ${failed.join(', ')}`);
    }
    console.log('\nAll done!');
    return;
  }

  // ── No RELEASE_ID — cross-release mode (requires START_ID) ──────────────
  if (!hasReleaseId) {
    if (!startId) {
      console.error('Usage: RELEASE_ID=N [START_ID=X] [PICK=1] [NEW=1] npx tsx scripts/generate-art.ts');
      console.error('       or: START_ID=X PICK=1 [NEW=1] npx tsx scripts/generate-art.ts  (cross-release)');
      console.error(`Releases with prompts: ${Object.keys(PROMPTS_BY_RELEASE).join(', ')}`);
      process.exit(1);
    }

    let queue = getAllPrompts();
    const startIdx = queue.findIndex(p => p.id === startId);
    if (startIdx === -1) {
      console.error(`START_ID=${startId} not found in any release prompts`);
      process.exit(1);
    }
    queue = queue.slice(startIdx);

    if (newOnly) {
      const { data: existing } = await supabase.from('cards').select('id').not('art_url', 'is', null);
      const doneIds = new Set((existing ?? []).map((c: any) => c.id));
      const before = queue.length;
      queue = queue.filter(p => !doneIds.has(p.id));
      console.log(`Cross-release: ${queue.length} cards to pick (skipped ${before - queue.length} with existing art)`);
    } else {
      console.log(`Cross-release: ${queue.length} cards from id=${startId} onward`);
    }

    await runPickServer(queue);
    return;
  }

  // ── RELEASE_ID provided ──────────────────────────────────────────────────
  const entry = PROMPTS_BY_RELEASE[releaseNum!];
  if (!entry) {
    const valid = Object.keys(PROMPTS_BY_RELEASE).join(', ');
    console.error(`No prompts for RELEASE_ID=${releaseNum}. Releases with prompts: ${valid}`);
    process.exit(1);
  }

  const startIdx = startId ? entry.prompts.findIndex(p => p.id === startId) : 0;
  if (startId && startIdx === -1) {
    console.error(`START_ID=${startId} not found in R${releaseNum} prompts`);
    process.exit(1);
  }

  let cards: CardEntry[] = entry.prompts.slice(startIdx).map(p => ({
    ...p,
    releaseNum: releaseNum!,
    dbReleaseId: entry.dbReleaseId,
  }));

  if (newOnly) {
    const { data: existing } = await supabase
      .from('cards').select('id').eq('release_id', entry.dbReleaseId).not('art_url', 'is', null);
    const doneIds = new Set((existing ?? []).map((c: any) => c.id));
    const before = cards.length;
    cards = cards.filter(p => !doneIds.has(p.id));
    console.log(`R${releaseNum}: ${cards.length} cards (skipped ${before - cards.length} with existing art)`);
  }

  // ── PICK mode ────────────────────────────────────────────────────────────
  if (isPick) {
    await runPickServer(cards);
    return;
  }

  // ── Batch mode ───────────────────────────────────────────────────────────
  console.log(`\nR${releaseNum}: generating ${cards.length} cards\n`);
  const failed: string[] = [];
  for (const card of cards) {
    try {
      await generateAndUpload(card);
    } catch (err: any) {
      console.warn(`  ⚠ SKIPPED ${card.name} (id=${card.id}): ${err?.message ?? err}`);
      failed.push(`${card.name} (id=${card.id})`);
    }
    await new Promise(r => setTimeout(r, 1500));
  }
  if (failed.length > 0) {
    console.log(`\nFailed cards (${failed.length}): ${failed.join(', ')}`);
  }
  console.log('\nAll done!');
}

main().catch(console.error);
